                        "Read a document's MIME type, page count, and language without extracting the body text.",
                        "SELECT meta['Content-Type'] AS ct FROM tika.main.metadata('Some bytes.'::BLOB);",
                        "Read a single metadata field from the `meta` MAP."));
    }

    /**
     * Static result schema of {@code metadata} (VGI307), as the structured
     * {@code vgi.result_columns_schema} JSON array of {@code {name,type,description}}.
     * The shape is fixed (unlike {@code extract_text}, which has a {@code by_page}
     * variant), so a static schema is the correct carrier.
     */
    static final String RESULT_COLUMNS_SCHEMA =
            "[\n"
                    + "  {\"name\": \"mime\", \"type\": \"VARCHAR\", \"description\": "
                    + "\"Detected media type, e.g. application/pdf.\"},\n"
                    + "  {\"name\": \"n_pages\", \"type\": \"INTEGER\", \"description\": "
                    + "\"Page/slide/sheet count when the format reports it, else NULL.\"},\n"
                    + "  {\"name\": \"lang\", \"type\": \"VARCHAR\", \"description\": "
                    + "\"Document language code if Tika reported one, else NULL.\"},\n"
                    + "  {\"name\": \"meta\", \"type\": \"MAP(VARCHAR, VARCHAR)\", \"description\": "
                    + "\"Full Tika metadata bag as a MAP(VARCHAR, VARCHAR).\"},\n"
                    + "  {\"name\": \"error\", \"type\": \"VARCHAR\", \"description\": "
                    + "\"Per-row parse error message, or NULL on success.\"}\n"
                    + "]";

    @Override public List<ArgSpec> argumentSpecs() {
        // Polymorphic doc arg (VARCHAR path or BLOB bytes) — see ExtractFunction.
        return List.of(
                Meta.anyArg("doc", 0,
                        "The document whose metadata to read. Pass either a filesystem path "
                                + "(the worker opens the file) or the raw document bytes inline; "
                                + "the worker dispatches on the runtime value."),
                Meta.namedArg("strict", Schemas.BOOL, "false",
                        "When true, re-raise any parse error and fail the query instead of "
                                + "capturing it in the `error` column (NULL metadata). Defaults to "
                                + "false (errors are captured per-row)."));
    }

    @Override public BindResponse onBind(TableBindParams p) {
        return BindResponse.forSchema(SchemaUtil.serializeSchema(TikaSchemas.METADATA_SCHEMA));
    }

    @Override public long cardinality(TableBindParams p) { return 1L; }

    @Override public TableProducerState createProducer(TableInitParams params) {
        Arguments a = params.arguments();
        Object docValue = a.positionalAt(0);
        ArrowType docType = a.positionalTypeAt(0);
        DocInput input = DocInput.fromArgument(docValue, docType);
        return new State(input,
                ParameterExtractor.of(a).named("strict").asBool().orElse(false), engine);
    }

    public static final class State extends TableProducerState {
        public byte[] bytes;
        public String path;
        public boolean strict;
        public boolean done;
        public transient TikaEngine engine;

        public State() {}

        State(DocInput input, boolean strict, TikaEngine engine) {
            this.bytes = input.bytes();
            this.path = input.path() == null ? null : input.path().toString();
            this.strict = strict;
            this.engine = engine;
        }

        private TikaEngine engine() { return engine != null ? engine : TikaEngine.shared(); }

        @Override public void produceTick(OutputCollector out, CallContext ctx) {
            if (done) { out.finish(); return; }
            done = true;
            Path p = path == null ? null : Path.of(path);
            TikaEngine.ExtractResult r = engine().metadataOnly(bytes, p);
            if (strict && r.error() != null) {
                throw new RuntimeException("tika.metadata failed: " + r.error());
            }
            VectorSchemaRoot root = TikaSchemas.metadataRow(Allocators.root(), r);
            out.emit(root);
            out.finish();
        }
    }
}

package farm.query.vgi.tika;

import farm.query.vgi.function.Arguments;
import farm.query.vgi.function.FunctionMetadata;
import farm.query.vgi.protocol.FunctionExample;
import farm.query.vgi.scalar.ScalarFn;
import farm.query.vgi.scalar.Setting;
import farm.query.vgi.scalar.Vector;
import farm.query.vgi.types.Schemas;

import java.util.List;
import org.apache.arrow.vector.FieldVector;
import org.apache.arrow.vector.VarBinaryVector;
import org.apache.arrow.vector.VarCharVector;
import org.apache.arrow.vector.types.pojo.ArrowType;
import org.apache.arrow.vector.types.pojo.Schema;
import org.apache.arrow.vector.util.Text;

import java.nio.file.Path;

/**
 * {@code tika.ocr(bytes | path, lang := 'eng') -> VARCHAR} — OCR an image or
 * scanned PDF via Tika's Tesseract parser. {@code lang} is a {@code +}-joined
 * trained-data list (e.g. {@code 'eng+deu'}).
 *
 * <p>Guarded by Tesseract availability: if the {@code tesseract} binary is not
 * on {@code PATH}, every row returns NULL rather than failing the query.
 */
public final class OcrFunction extends ScalarFn {

    private final TikaEngine engine;

    public OcrFunction() { this(TikaEngine.shared()); }
    public OcrFunction(TikaEngine engine) { this.engine = engine; }

    @Override public String name() { return "ocr"; }

    @Override public String description() {
        return "OCR an image or scanned PDF (bytes or path) via Tika's Tesseract parser; "
                + "returns NULL when Tesseract is unavailable.";
    }

    @Override public FunctionMetadata metadata() {
        return FunctionMetadata.describe(description())
                .withCategories("document", "ocr", "tika")
                .withTag("vgi.category", "Optical Character Recognition")
                .withExamples(List.of(
                        new FunctionExample(
                                "SELECT tika.main.ocr('/docs/scan.png');",
                                "OCR an image file with the default English model "
                                        + "(NULL if Tesseract is not installed).",
                                null),
                        new FunctionExample(
                                "SELECT tika.main.ocr('/docs/scan.png'::BLOB);",
                                "OCR image bytes (a BLOB) instead of a path "
                                        + "(NULL if Tesseract is not installed).",
                                null)))
                .withTags(Meta.objectTags(
                        "OCR Image or Scanned PDF",
                        "## ocr\n\n"
                                + "Run optical character recognition over an image or a scanned PDF using "
                                + "Apache Tika's Tesseract parser, returning the recognized text.\n\n"
                                + "**Input** — an `any`-typed document argument (`BLOB` bytes or `VARCHAR` "
                                + "path) plus an optional `lang` setting. `lang` is a `+`-joined list of "
                                + "Tesseract trained-data languages, e.g. `'eng'` (default) or `'eng+deu'`.\n\n"
                                + "**Output** — a `VARCHAR` of the OCR'd text.\n\n"
                                + "**Important** — OCR requires the system `tesseract` binary on `PATH`. "
                                + "When it is absent the function returns `NULL` for every row instead of "
                                + "failing the query, so pipelines stay resilient. Use this for image-only "
                                + "documents where `extract_text` returns little or no text.",
                        "# ocr\n\n"
                                + "Returns text recognized from an image or scanned PDF as a `VARCHAR`.\n\n"
                                + "## Usage\n\n"
                                + "Pass image bytes or a path; optionally set `lang` to a `+`-joined "
                                + "trained-data list (`'eng+deu'`) to recognize multiple scripts.\n\n"
                                + "## Notes\n\n"
                                + "- Requires the `tesseract` system binary; returns `NULL` when it is not "
                                + "installed rather than raising.\n"
                                + "- Returns `NULL` for a `NULL` input.\n"
                                + "- For born-digital documents prefer `extract_text`; reach for `ocr` when the "
                                + "content is rasterized.",
                        "ocr", "tesseract", "optical character recognition", "scanned",
                        "image text", "scan", "recognize text", "image to text"))
                .withTag("vgi.example_queries", Main.exampleQueriesTag(
                        "SELECT tika.main.ocr('/docs/scan.png');",
                        "OCR an image file with the default English model (NULL if Tesseract is not installed).",
                        "SELECT tika.main.ocr('/docs/scan.png'::BLOB);",
                        "OCR image bytes (a BLOB) instead of a path (NULL if Tesseract is not installed)."));
    }

    @Override protected ArrowType outputType(Schema inputSchema, Arguments args) {
        return Schemas.UTF8;
    }

    public void compute(@Vector(value = "doc", any = true,
                                doc = "The image or scanned PDF to OCR. Pass either the raw bytes "
                                        + "inline or a filesystem path the worker opens; the "
                                        + "worker dispatches on the runtime value.")
                        FieldVector in,
                        @Setting(default_ = "eng") String lang,
                        VarCharVector out) {
        String ocrLang = (lang == null || lang.isBlank()) ? "eng" : lang;
        boolean available = engine.tesseractAvailable();
        int n = in.getValueCount();
        for (int i = 0; i < n; i++) {
            if (in.isNull(i) || !available) { out.setNull(i); continue; }
            String text;
            if (in instanceof VarBinaryVector b) {
                text = engine.ocr(b.get(i), null, ocrLang);
            } else if (in instanceof VarCharVector s) {
                text = engine.ocr(null, Path.of(s.getObject(i).toString()), ocrLang);
            } else {
                DocInput input = DocInput.fromArgument(in.getObject(i), in.getField().getType());
                text = engine.ocr(input.bytes(), input.path(), ocrLang);
            }
            if (text == null) out.setNull(i);
            else out.setSafe(i, new Text(text));
        }
    }
}

package farm.query.vgi.tika;

import org.apache.tika.detect.Detector;
import org.apache.tika.io.TikaInputStream;
import org.apache.tika.metadata.HttpHeaders;
import org.apache.tika.metadata.Metadata;
import org.apache.tika.metadata.TikaCoreProperties;
import org.apache.tika.mime.MediaType;
import org.apache.tika.parser.AutoDetectParser;
import org.apache.tika.parser.ParseContext;
import org.apache.tika.parser.Parser;
import org.apache.tika.parser.ocr.TesseractOCRConfig;
import org.apache.tika.parser.ocr.TesseractOCRParser;
import org.apache.tika.parser.pages.TextPolicy;
import org.apache.tika.parser.pdf.PDFParserConfig;
import org.apache.tika.sax.BodyContentHandler;
import org.xml.sax.ContentHandler;

import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.PDFTextStripper;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Thin, thread-safe wrapper around Apache Tika's {@link AutoDetectParser}.
 *
 * <p>One instance is shared across every function and call. Tika's parser and
 * detector are stateless and safe to reuse; the per-parse state lives in the
 * {@link Metadata} / {@link ParseContext} created per call. The first parse pays
 * the class-load cost (PDFBox/POI), which the persistent VGI worker amortizes
 * across queries.
 */
public final class TikaEngine {

    private static final TikaEngine SHARED = new TikaEngine();

    /** Tika caps extracted text at 100k chars by default; -1 = unbounded. */
    private static final int WRITE_LIMIT = -1;

    private final AutoDetectParser parser;
    private final Detector detector;

    public TikaEngine() {
        // Tika 4 removed TikaConfig; the no-arg AutoDetectParser loads the default
        // (SPI-discovered) parsers and detector.
        this.parser = new AutoDetectParser();
        this.detector = parser.getDetector();
    }

    public static TikaEngine shared() {
        return SHARED;
    }

    /** Result of a single document parse. {@code error} is non-null on failure. */
    public record ExtractResult(
            String content,
            String mime,
            Integer nPages,
            String lang,
            Map<String, String> meta,
            String error) {

        static ExtractResult failure(String error) {
            return new ExtractResult(null, null, null, null, Map.of(), error);
        }
    }

    // ---- bytes / path acquisition -----------------------------------------

    /** Open a path as a stream, or wrap an in-memory byte[]. Caller closes. */
    private static TikaInputStream open(byte[] bytes, Path path) throws IOException {
        if (path != null) {
            return TikaInputStream.get(path);
        }
        return TikaInputStream.get(bytes != null ? bytes : new byte[0]);
    }

    // ---- full extraction (text + metadata) --------------------------------

    public ExtractResult extract(byte[] bytes, Path path, boolean ocrEnabled, String ocrLang) {
        Metadata metadata = new Metadata();
        if (path != null) {
            metadata.set(TikaCoreProperties.RESOURCE_NAME_KEY, path.getFileName().toString());
        }
        ContentHandler handler = new BodyContentHandler(WRITE_LIMIT);
        ParseContext context = parseContext(ocrEnabled, ocrLang);
        try (TikaInputStream in = open(bytes, path)) {
            parser.parse(in, handler, metadata, context);
        } catch (Exception e) {
            return ExtractResult.failure(describe(e));
        }
        return resultFrom(handler.toString(), metadata, null);
    }

    /**
     * Per-page extraction. For PDFs we use PDFBox's {@link PDFTextStripper} to
     * split the text-layer body on real page boundaries, yielding one result per
     * page. For every other format (and for image-only / scanned PDFs handled via
     * OCR) Tika has no page-boundary signal, so we fall back to a single result
     * carrying the whole body with {@code page = n_pages}.
     *
     * <p>Each per-page result repeats the document-level {@code mime}, {@code lang},
     * and total {@code n_pages}; the {@code meta} bag rides only on the first page
     * to avoid duplicating the (potentially large) document metadata on every row.
     */
    public List<PageResult> extractByPage(byte[] bytes, Path path, boolean ocrEnabled, String ocrLang) {
        ExtractResult whole = extract(bytes, path, ocrEnabled, ocrLang);
        if (whole.error() != null) {
            return List.of(new PageResult(whole.nPages() != null ? whole.nPages() : 1, whole));
        }

        boolean isPdf = "application/pdf".equals(whole.mime());
        // Only split a PDF's text layer when OCR is off; with OCR the body comes
        // from Tika's Tesseract path, which PDFTextStripper cannot reproduce.
        if (isPdf && !ocrEnabled) {
            List<PageResult> pages = splitPdfPages(bytes, path, whole);
            if (pages != null) {
                return pages;
            }
        }

        int total = whole.nPages() != null ? whole.nPages() : 1;
        return List.of(new PageResult(total, whole));
    }

    /**
     * Split a PDF's text layer into one {@link PageResult} per page. Returns
     * {@code null} on any failure so the caller can fall back to whole-document
     * behaviour (never throws — by_page must not regress error capture).
     */
    private List<PageResult> splitPdfPages(byte[] bytes, Path path, ExtractResult whole) {
        try (PDDocument doc = load(bytes, path)) {
            int total = doc.getNumberOfPages();
            if (total <= 0) {
                return List.of(new PageResult(0, whole));
            }
            PDFTextStripper stripper = new PDFTextStripper();
            List<PageResult> pages = new ArrayList<>(total);
            for (int p = 1; p <= total; p++) {
                stripper.setStartPage(p);
                stripper.setEndPage(p);
                String pageText = stripper.getText(doc);
                // Document metadata (the meta bag + lang) rides on page 1 only.
                Map<String, String> meta = p == 1 ? whole.meta() : Map.of();
                String lang = p == 1 ? whole.lang() : null;
                ExtractResult pageResult = new ExtractResult(
                        pageText, whole.mime(), total, lang, meta, null);
                pages.add(new PageResult(p, pageResult));
            }
            return pages;
        } catch (Exception e) {
            return null;
        }
    }

    private static PDDocument load(byte[] bytes, Path path) throws IOException {
        if (path != null) {
            return Loader.loadPDF(path.toFile());
        }
        return Loader.loadPDF(bytes != null ? bytes : new byte[0]);
    }

    /** One page of a by-page extraction: a 1-based ordinal plus its row payload. */
    public record PageResult(int page, ExtractResult result) {}

    /** Metadata-only extraction (no body text). */
    public ExtractResult metadataOnly(byte[] bytes, Path path) {
        Metadata metadata = new Metadata();
        if (path != null) {
            metadata.set(TikaCoreProperties.RESOURCE_NAME_KEY, path.getFileName().toString());
        }
        // A no-op handler: parse for side effects on Metadata only.
        ContentHandler handler = new BodyContentHandler(0);
        ParseContext context = parseContext(false, null);
        try (TikaInputStream in = open(bytes, path)) {
            parser.parse(in, handler, metadata, context);
        } catch (org.apache.tika.exception.WriteLimitReachedException limit) {
            // Expected: handler limit is 0, we only wanted metadata.
        } catch (Exception e) {
            return new ExtractResult(null, null, null, null, Map.of(), describe(e));
        }
        ExtractResult full = resultFrom(null, metadata, null);
        return new ExtractResult(null, full.mime(), full.nPages(), full.lang(), full.meta(), null);
    }

    private ExtractResult resultFrom(String content, Metadata metadata, String error) {
        Map<String, String> meta = new LinkedHashMap<>();
        for (String name : metadata.names()) {
            meta.put(name, String.join("; ", metadata.getValues(name)));
        }
        String mime = metadata.get(HttpHeaders.CONTENT_TYPE);
        Integer nPages = parseIntOrNull(metadata.get("xmpTPg:NPages"));
        if (nPages == null) {
            nPages = parseIntOrNull(metadata.get("Page-Count"));
        }
        String lang = metadata.get(TikaCoreProperties.LANGUAGE);
        return new ExtractResult(content, mime, nPages, lang, meta, error);
    }

    // ---- mime detection ----------------------------------------------------

    public String detectMime(byte[] bytes, Path path) {
        Metadata metadata = new Metadata();
        if (path != null) {
            metadata.set(TikaCoreProperties.RESOURCE_NAME_KEY, path.getFileName().toString());
        }
        try (TikaInputStream in = open(bytes, path)) {
            MediaType type = detector.detect(in, metadata, new ParseContext());
            return type == null ? null : type.toString();
        } catch (Exception e) {
            return null;
        }
    }

    // ---- OCR ---------------------------------------------------------------

    /** Run image/scanned-PDF OCR via Tesseract. Returns null if OCR is unavailable. */
    public String ocr(byte[] bytes, Path path, String lang) {
        if (!tesseractAvailable()) {
            return null;
        }
        Metadata metadata = new Metadata();
        ContentHandler handler = new BodyContentHandler(WRITE_LIMIT);
        ParseContext context = parseContext(true, lang);
        try (TikaInputStream in = open(bytes, path)) {
            parser.parse(in, handler, metadata, context);
        } catch (Exception e) {
            return null;
        }
        return handler.toString();
    }

    public boolean tesseractAvailable() {
        try {
            return new TesseractOCRParser().hasTesseract();
        } catch (Exception e) {
            return false;
        }
    }

    // ---- parse context wiring ---------------------------------------------

    private ParseContext parseContext(boolean ocrEnabled, String ocrLang) {
        ParseContext context = new ParseContext();
        // Recursive parsing of embedded docs uses the same auto-detect parser.
        context.set(Parser.class, parser);

        TesseractOCRConfig ocrConfig = new TesseractOCRConfig();
        if (ocrEnabled && ocrLang != null && !ocrLang.isBlank()) {
            ocrConfig.setLanguage(ocrLang);
        }
        if (!ocrEnabled) {
            ocrConfig.setSkipOcr(true);
        }
        context.set(TesseractOCRConfig.class, ocrConfig);

        PDFParserConfig pdfConfig = new PDFParserConfig();
        // Only OCR scanned PDFs (no text layer) when OCR is explicitly enabled.
        // Tika 4: the PDF OCR strategy is the page text policy (EXTRACT = no OCR).
        pdfConfig.pages().setText(ocrEnabled
                ? TextPolicy.EXTRACT_AND_OCR
                : TextPolicy.EXTRACT);
        pdfConfig.setExtractInlineImages(false);
        context.set(PDFParserConfig.class, pdfConfig);

        return context;
    }

    private static Integer parseIntOrNull(String s) {
        if (s == null || s.isBlank()) return null;
        try {
            return Integer.valueOf(s.trim());
        } catch (NumberFormatException e) {
            return null;
        }
    }

    private static String describe(Throwable t) {
        String msg = t.getMessage();
        String type = t.getClass().getSimpleName();
        return (msg == null || msg.isBlank()) ? type : type + ": " + msg;
    }
}

package farm.query.vgi.tika;

import farm.query.vgi.types.Schemas;
import org.apache.arrow.memory.BufferAllocator;
import org.apache.arrow.vector.IntVector;
import org.apache.arrow.vector.VarCharVector;
import org.apache.arrow.vector.VectorSchemaRoot;
import org.apache.arrow.vector.complex.MapVector;
import org.apache.arrow.vector.complex.impl.UnionMapWriter;
import org.apache.arrow.vector.types.pojo.ArrowType;
import org.apache.arrow.vector.types.pojo.Field;
import org.apache.arrow.vector.types.pojo.FieldType;
import org.apache.arrow.vector.types.pojo.Schema;
import org.apache.arrow.vector.util.Text;

import java.util.List;
import java.util.Map;

/**
 * Shared Arrow schemas + batch-builder for the extraction family
 * ({@code extract_text}, {@code extract_all}, {@code metadata}).
 *
 * <p>The {@code meta} column is a DuckDB {@code MAP(VARCHAR, VARCHAR)} — over
 * Arrow that is {@code Map<entries: struct<key: utf8 not null, value: utf8>>}.
 */
public final class TikaSchemas {

    private TikaSchemas() {}

    /** Full extract output: (content, mime, n_pages, lang, meta, error). */
    public static final Schema EXTRACT_SCHEMA = new Schema(List.of(
            commented("content", Schemas.UTF8, "Extracted plain-text body of the document, or NULL on error."),
            commented("mime", Schemas.UTF8, "Detected media type (e.g. application/pdf)."),
            commented("n_pages", Schemas.INT32, "Page / slide / sheet count when the format reports it, else NULL."),
            commented("lang", Schemas.UTF8, "Document language code if Tika reported one in the metadata."),
            mapField("meta", "Full Tika metadata bag as a MAP(VARCHAR, VARCHAR)."),
            commented("error", Schemas.UTF8, "Parse error message for this row, or NULL on success.")));

    /** by_page variant: extract output plus a leading {@code page} column. */
    public static final Schema EXTRACT_BY_PAGE_SCHEMA = new Schema(List.of(
            commented("page", Schemas.INT32, "1-based page / slide / sheet ordinal."),
            commented("content", Schemas.UTF8, "Extracted plain-text body of this page, or NULL on error."),
            commented("mime", Schemas.UTF8, "Detected media type (e.g. application/pdf)."),
            commented("n_pages", Schemas.INT32, "Total page count of the source document."),
            commented("lang", Schemas.UTF8, "Document language code if Tika reported one."),
            mapField("meta", "Full Tika metadata bag as a MAP(VARCHAR, VARCHAR)."),
            commented("error", Schemas.UTF8, "Parse error message for this row, or NULL on success.")));

    /** metadata() output: extract schema minus content. */
    public static final Schema METADATA_SCHEMA = new Schema(List.of(
            commented("mime", Schemas.UTF8, "Detected media type (e.g. application/pdf)."),
            commented("n_pages", Schemas.INT32, "Page / slide / sheet count when reported, else NULL."),
            commented("lang", Schemas.UTF8, "Document language code if Tika reported one."),
            mapField("meta", "Full Tika metadata bag as a MAP(VARCHAR, VARCHAR)."),
            commented("error", Schemas.UTF8, "Parse error message for this row, or NULL on success.")));

    static Field commented(String name, ArrowType type, String comment) {
        return new Field(name, new FieldType(true, type, null, Map.of("comment", comment)), null);
    }

    /** A nullable MAP(VARCHAR, VARCHAR) field carrying a column comment. */
    static Field mapField(String name, String comment) {
        Field key = new Field(MapVector.KEY_NAME,
                new FieldType(false, Schemas.UTF8, null), null);
        Field value = new Field(MapVector.VALUE_NAME,
                new FieldType(true, Schemas.UTF8, null), null);
        Field entries = new Field(MapVector.DATA_VECTOR_NAME,
                new FieldType(false, new ArrowType.Struct(), null), List.of(key, value));
        return new Field(name,
                new FieldType(true, new ArrowType.Map(false), null, Map.of("comment", comment)),
                List.of(entries));
    }

    /** Write one metadata MAP cell at {@code row} into a {@link MapVector}. */
    static void writeMap(MapVector mapVector, int row, Map<String, String> entries) {
        UnionMapWriter writer = mapVector.getWriter();
        writer.setPosition(row);
        writer.startMap();
        if (entries != null) {
            for (Map.Entry<String, String> e : entries.entrySet()) {
                if (e.getKey() == null) continue;
                writer.startEntry();
                writer.key().varChar().writeVarChar(e.getKey());
                if (e.getValue() != null) {
                    writer.value().varChar().writeVarChar(e.getValue());
                } else {
                    writer.value().varChar().writeNull();
                }
                writer.endEntry();
            }
        }
        writer.endMap();
    }

    // ---- batch builders ----------------------------------------------------

    /**
     * Build a one-row {@link VectorSchemaRoot} for {@link #EXTRACT_SCHEMA} (or
     * a zero-row root when the document split into pages handled elsewhere).
     */
    static VectorSchemaRoot singleRow(BufferAllocator alloc, TikaEngine.ExtractResult r) {
        VectorSchemaRoot root = VectorSchemaRoot.create(EXTRACT_SCHEMA, alloc);
        root.allocateNew();
        setUtf8(root, "content", 0, r.content());
        setUtf8(root, "mime", 0, r.mime());
        setInt(root, "n_pages", 0, r.nPages());
        setUtf8(root, "lang", 0, r.lang());
        writeMap((MapVector) root.getVector("meta"), 0, r.meta());
        setUtf8(root, "error", 0, r.error());
        root.setRowCount(1);
        return root;
    }

    static VectorSchemaRoot metadataRow(BufferAllocator alloc, TikaEngine.ExtractResult r) {
        VectorSchemaRoot root = VectorSchemaRoot.create(METADATA_SCHEMA, alloc);
        root.allocateNew();
        setUtf8(root, "mime", 0, r.mime());
        setInt(root, "n_pages", 0, r.nPages());
        setUtf8(root, "lang", 0, r.lang());
        writeMap((MapVector) root.getVector("meta"), 0, r.meta());
        setUtf8(root, "error", 0, r.error());
        root.setRowCount(1);
        return root;
    }

    static void setUtf8(VectorSchemaRoot root, String col, int row, String value) {
        VarCharVector v = (VarCharVector) root.getVector(col);
        if (value == null) {
            v.setNull(row);
        } else {
            v.setSafe(row, new Text(value));
        }
    }

    static void setInt(VectorSchemaRoot root, String col, int row, Integer value) {
        IntVector v = (IntVector) root.getVector(col);
        if (value == null) {
            v.setNull(row);
        } else {
            v.setSafe(row, value);
        }
    }
}
